CREATE OR REPLACE FUNCTION nexus.topics_recount_doc_count(
    p_tenant_id text,
    p_dry_run   boolean DEFAULT false
) RETURNS TABLE(tenant_id text, topic_id bigint, label text, collection text, doc_count integer, actual_count bigint)
LANGUAGE plpgsql
SECURITY INVOKER
AS $fn$
DECLARE
    r           record;
    v_corrected integer := 0;
BEGIN
    FOR r IN SELECT * FROM nexus.topics_doc_count_drift(p_tenant_id)
    LOOP
        IF NOT p_dry_run THEN
            UPDATE nexus.topics t
               SET doc_count = r.actual_count
             WHERE t.tenant_id = r.tenant_id AND t.id = r.topic_id;
            v_corrected := v_corrected + 1;
            RAISE NOTICE 'topics_recount_doc_count: topic %.% doc_count corrected % -> %',
                r.tenant_id, r.topic_id, r.doc_count, r.actual_count;
        END IF;
        tenant_id     := r.tenant_id;
        topic_id      := r.topic_id;
        label         := r.label;
        collection    := r.collection;
        doc_count     := r.doc_count;
        actual_count  := r.actual_count;
        RETURN NEXT;
    END LOOP;
    IF NOT p_dry_run THEN
        RAISE NOTICE 'topics_recount_doc_count: % topic(s) corrected (tenant_id=%)',
            v_corrected, COALESCE(p_tenant_id, 'ALL');
    END IF;
END;
$fn$;
